import{_ as e,c as a,o as s,V as o}from"./chunks/framework.5a924dd5.js";const y=JSON.parse('{"title":"Framework packages","description":"","frontmatter":{"title":"Framework packages","lang":"en-US"},"headers":[],"relativePath":"frameworks.md","filePath":"frameworks.md"}'),t={name:"frameworks.md"},r=o(`<h1 id="framework-packages" tabindex="-1">Framework packages <a class="header-anchor" href="#framework-packages" aria-label="Permalink to &quot;Framework packages&quot;">​</a></h1><p><strong>What we will talk about:</strong></p><nav class="table-of-contents"><ul><li><a href="#install-the-packages-for-your-framework">Install the packages for your framework</a><ul><li><a href="#hapi">Hapi</a></li></ul></li><li><a href="#express-5">Express 5</a></li></ul></nav><h2 id="install-the-packages-for-your-framework" tabindex="-1">Install the packages for your framework <a class="header-anchor" href="#install-the-packages-for-your-framework" aria-label="Permalink to &quot;Install the packages for your framework&quot;">​</a></h2><p><code>@tsoa/runtime</code> does not install a web framework. Its framework packages are optional peer dependencies, so install the ones for the framework you use:</p><table><thead><tr><th>Framework</th><th>Packages</th></tr></thead><tbody><tr><td>Express</td><td><code>express</code>, <code>@types/express</code> (4 or 5)</td></tr><tr><td>Koa</td><td><code>koa</code>, <code>@types/koa</code> (2 or 3)</td></tr><tr><td>Hapi</td><td><code>@hapi/hapi</code>, <code>@hapi/boom</code></td></tr></tbody></table><p>Routes that accept file uploads also import <code>multer</code> (Express) or <code>@koa/multer</code> (Koa), so install that package as well. See <a href="./file-upload.html">File upload</a>.</p><h3 id="hapi" tabindex="-1">Hapi <a class="header-anchor" href="#hapi" aria-label="Permalink to &quot;Hapi&quot;">​</a></h3><p>The generated Hapi routes import <code>boomify</code> and <code>isBoom</code> from <code>@hapi/boom</code>. <code>@hapi/hapi</code> depends on it, but list it in your own <code>package.json</code> as well: with pnpm or another strict layout, the routes cannot resolve it otherwise.</p><h2 id="express-5" tabindex="-1">Express 5 <a class="header-anchor" href="#express-5" aria-label="Permalink to &quot;Express 5&quot;">​</a></h2><p>tsoa supports Express 4 and 5. It does not change its runtime for Express 5 defaults. Set these two options to keep query and form parsing the same as on Express 4:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">query parser</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">extended</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// bracket syntax such as ?filter[a]=x and ?ids[]=1</span></span>
<span class="line"><span style="color:#A6ACCD;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">use</span><span style="color:#A6ACCD;">(express</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">urlencoded</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">{</span><span style="color:#A6ACCD;"> </span><span style="color:#F07178;">extended</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#FF9CAC;">true</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;">))</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// nested form fields such as a[b]=1</span></span></code></pre></div><ul><li>With <code>express.json()</code>, a request without a body leaves <code>req.body</code> <code>undefined</code> on Express 5, so a required <code>@Body()</code> fails validation. Express 4 and body-parser 1 leave <code>{}</code>, which passes if the body schema accepts an empty object.</li><li>Express 5 reserves <code>()[]?+!</code> in route paths and requires a name for each <code>*</code> wildcard. A decorator path that breaks these rules fails at route registration. tsoa emits path parameters as <code>:name</code>. See the <a href="https://expressjs.com/en/guide/migrating-5.html#path-route-matching-syntax" target="_blank" rel="noreferrer">Express 5 migration guide</a>.</li><li>Express 5 forwards a rejected promise from an async custom <code>@Middlewares</code> function to the error handler. On Express 4, catch the error and call <code>next(err)</code>, or the unhandled rejection can stop the Node process.</li></ul>`,13),n=[r];function l(p,c,d,i,h,u){return s(),a("div",null,n)}const f=e(t,[["render",l]]);export{y as __pageData,f as default};
